* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #151821;
  background: #f4f6f8;
}

.pos-analysis {
  min-height: 100vh;
  padding: 22px;
  background: #f4f6f8;
}

.report-header {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: flex-start;
  margin-bottom: 18px;
}

.report-header p {
  margin: 0 0 4px;
  font-size: 13px;
  font-weight: 800;
  color: #2257d6;
  text-transform: uppercase;
}

.report-header h1 {
  margin: 0;
  font-size: 34px;
  letter-spacing: 0;
}

.report-header span {
  display: block;
  margin-top: 6px;
  color: #627086;
  font-weight: 700;
}

.actions {
  display: flex;
  gap: 10px;
}

.actions button {
  border: 0;
  min-height: 40px;
  padding: 0 14px;
  border-radius: 6px;
  background: #151b31;
  color: white;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-weight: 800;
  cursor: pointer;
}

.kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 14px;
}

.kpi-grid article {
  background: white;
  border: 1px solid #dce4ef;
  border-radius: 8px;
  padding: 18px;
  min-height: 124px;
  box-shadow: 0 8px 28px rgba(22, 34, 54, 0.07);
  display: grid;
  gap: 8px;
}

.kpi-grid svg {
  color: #2257d6;
}

.kpi-grid span {
  color: #657285;
  font-weight: 800;
}

.kpi-grid strong {
  font-size: 26px;
  line-height: 1;
}

.content-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 14px;
}

.panel {
  background: white;
  border: 1px solid #dce4ef;
  border-radius: 8px;
  padding: 18px;
  box-shadow: 0 8px 28px rgba(22, 34, 54, 0.06);
}

.panel.wide {
  grid-column: span 1;
}

.panel-title {
  margin-bottom: 16px;
}

.panel-title h2 {
  margin: 0;
  font-size: 18px;
}

.panel-title span {
  display: block;
  margin-top: 4px;
  color: #69768a;
  font-size: 13px;
  font-weight: 700;
}

.hour-chart {
  height: 280px;
  display: grid;
  grid-template-columns: repeat(24, minmax(22px, 1fr));
  gap: 8px;
  align-items: end;
  overflow-x: auto;
  padding-bottom: 4px;
}

.hour {
  min-width: 30px;
  display: grid;
  grid-template-rows: 1fr auto auto;
  gap: 6px;
  text-align: center;
}

.bar-wrap {
  height: 190px;
  display: flex;
  align-items: end;
  justify-content: center;
  border-radius: 6px;
  background: #f1f5f9;
  overflow: hidden;
}

.bar {
  width: 100%;
  border-radius: 6px 6px 0 0;
  background: linear-gradient(180deg, #2257d6, #48a4ff);
}

.hour strong {
  font-size: 11px;
  color: #273246;
}

.hour span {
  font-size: 11px;
  color: #6b778a;
  font-weight: 800;
}

.list {
  display: grid;
  gap: 10px;
}

.list-row {
  min-height: 58px;
  padding: 12px;
  border: 1px solid #e2e8f0;
  border-radius: 7px;
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
}

.list-row strong,
.item-meta strong {
  display: block;
  font-size: 14px;
}

.list-row span,
.item-meta span {
  display: block;
  margin-top: 3px;
  color: #6b778a;
  font-size: 12px;
  font-weight: 700;
}

.list-row b {
  white-space: nowrap;
}

.items {
  display: grid;
  gap: 12px;
}

.item-row {
  display: grid;
  grid-template-columns: minmax(180px, 1fr) 1.6fr 120px;
  gap: 14px;
  align-items: center;
}

.item-bar {
  height: 12px;
  border-radius: 999px;
  background: #edf2f7;
  overflow: hidden;
}

.item-bar div {
  height: 100%;
  border-radius: 999px;
  background: #151b31;
}

.item-row b {
  text-align: right;
}

.empty {
  padding: 34px 14px;
  color: #7a8495;
  font-weight: 800;
  text-align: center;
  border: 1px dashed #d7dee9;
  border-radius: 8px;
  background: #f8fafc;
}

.report-footer {
  margin-top: 16px;
  color: #6d788a;
  font-size: 12px;
  font-weight: 700;
}

@media print {
  .no-print {
    display: none !important;
  }
  body,
  .pos-analysis {
    background: white;
  }
  .pos-analysis {
    padding: 0;
  }
  .panel,
  .kpi-grid article {
    box-shadow: none;
    break-inside: avoid;
  }
}

