                </div>
              );
            }) : <div className="empty">No item data</div>}
          </div>
        </article>
      </section>

      <footer className="report-footer">
        Printed: {safeText(model.printedAt)} by {safeText(model.printedBy)}
      </footer>
    </main>
  );
}

function render() {
  ReactDOM.render(<App />, document.getElementById("root"));
}

appsmith.onReady(() => {
  render();
  appsmith.onModelChange(render);
});
